// Bukhara morning carryover rejection / waste.
(function(){
 state.morningWasteDishes=[];state.morningWasteQty={};state.morningWasteBusy=false;
 const date=()=>{try{return state.home?.businessDate||businessDate()||''}catch{return state.home?.businessDate||''}};
 const actor=()=>localStorage.getItem('stolovaya:employee-name')||sessionStorage.getItem('stolovaya:employee-name')||'Буфетчик';
 const q=v=>{const x=n(v);return Number.isInteger(x)?String(x):String(Math.round(x*1000)/1000).replace('.',',')};
 const baseHome=homeScreen;homeScreen=function(){let html=baseHome();if(state.point!=='BUKHARA')return html;const button=`<button type="button" id="morning-waste-open" ${state.home?.submitted||state.home?.dayClosed?'disabled':''}><span>♻</span><div><b>Утиль утро</b></div></button>`;const anchor=/<button type="button" id="kitchen-supply-open"[\s\S]*?<\/button>/;return anchor.test(html)?html.replace(anchor,m=>m+button):html.replace(/<\/div>\s*<button[^>]*change-point/,button+'</div><button change-point')};
 async function open(){if(state.point!=='BUKHARA')return;state.screen='morning-waste';state.message='';state.morningWasteBusy=true;render();try{state.morningWasteDishes=await rpc('public_morning_waste_dishes',{p_token:state.token,p_point_code:state.point,p_business_date:date()});}catch(e){state.message=e.message||'Не удалось загрузить переходящий остаток'}finally{state.morningWasteBusy=false;render()}}
 function rows(){return(state.morningWasteDishes||[]).filter(x=>n(x.carryoverQty)>0)}
 function screen(){return `${header()}${back('Утиль утро')}<section class="question-card"><h2>Переходящий остаток</h2><p>Укажите только то количество, которое повар <b>не допускает к продаже сегодня</b>. Оно сразу уйдёт из доступного остатка.</p></section>${state.morningWasteBusy?'<div class="notice">Загружаем…</div>':rows().length?`<div class="morning-waste-list">${rows().map(x=>`<div class="morning-waste-row"><div><b>${esc(clean(x.name))}</b>${x.code?`<small>${esc(x.code)}</small>`:''}<small>Переходящий остаток: <b>${esc(q(x.carryoverQty+n(x.wasteQty)))}</b>${n(x.wasteQty)>0?` · уже в утиль: <b>${esc(q(x.wasteQty))}</b>`:''}</small></div><input data-morning-waste="${x.dishId}" inputmode="decimal" placeholder="Утиль" value="${esc(state.morningWasteQty[x.dishId]||'')}"></div>`).join('')}</div><div class="sticky-action"><button id="morning-waste-save" class="primary">Сохранить утиль</button></div>`:'<div class="notice">Переходящих остатков на сегодня нет.</div>'}${state.message?`<p class="toast">${esc(state.message)}</p>`:''}`}
 async function save(){const items=rows().filter(x=>n(state.morningWasteQty[x.dishId])>0);if(!items.length){state.message='Укажите количество хотя бы у одного блюда';render();return}state.morningWasteBusy=true;state.message='';render();try{for(const x of items)await rpc('public_add_morning_waste',{p_token:state.token,p_point_code:state.point,p_dish_id:x.dishId,p_quantity:n(state.morningWasteQty[x.dishId]),p_actor:actor(),p_business_date:date()});state.morningWasteQty={};await loadPoint();state.morningWasteDishes=await rpc('public_morning_waste_dishes',{p_token:state.token,p_point_code:state.point,p_business_date:date()});state.message='Утиль сохранён. Эти блюда исключены из доступного остатка.'}catch(e){state.message=e.message||'Не удалось сохранить утиль'}finally{state.morningWasteBusy=false;render()}}
 const baseRender=render;render=function(){if(state.screen==='morning-waste'){app.innerHTML=screen();bind();return}baseRender()};
 const baseBind=bind;bind=function(){baseBind();document.getElementById('morning-waste-open')?.addEventListener('click',open);document.querySelectorAll('[data-morning-waste]').forEach(i=>i.oninput=e=>{const v=e.target.value.replace(',','.');if(v&&!/^\d*(\.\d{0,3})?$/.test(v)){e.target.value=state.morningWasteQty[i.dataset.morningWaste]||'';return}state.morningWasteQty[i.dataset.morningWaste]=v});document.getElementById('morning-waste-save')?.addEventListener('click',save)};
 const st=document.createElement('style');st.textContent=`.morning-waste-list{display:flex;flex-direction:column;gap:8px;margin-bottom:90px}.morning-waste-row{display:flex;align-items:center;justify-content:space-between;gap:12px;background:#fff;border:1px solid #d8ddd9;border-radius:14px;padding:12px 14px}.morning-waste-row>div{display:flex;flex-direction:column;min-width:0}.morning-waste-row small{display:block;margin-top:4px;color:#68736d}.morning-waste-row input{width:92px;min-width:92px;text-align:center;font-size:17px}`;document.head.appendChild(st);
})();